def _should_fallback_on_response(self, response: ModelResponse) -> bool:
    """Determine if a response should trigger a fallback."""
    if isinstance(self.fallback_on, list):
        # Check if any handler is a response handler (callable with ModelResponse)
        for handler in self.fallback_on:
            if self._is_response_handler(handler):
                return handler(response)
        return False
    # Single handler case
    return self._is_response_handler(self.fallback_on) and self.fallback_on(response)

def _is_response_handler(self, handler: Callable) -> bool:
    """Check if a handler is a response handler (accepts ModelResponse)."""
    import inspect
    sig = inspect.signature(handler)
    parameters = sig.parameters.values()
    return len(parameters) > 0 and parameters[0].annotation == ModelResponse
